using System;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Globalization;
namespace BeamScheduleFormatter {
partial class SlabEstimatorForm {
 void ReplaceManualSchedule(SlabScheduleRow value){SlabScheduleRow previous;if(!schedules.TryGetValue(value.Mark,out previous)||!previous.Manual)throw new Exception("Choose a manual slab schedule.");int index=sourceFiles.FindIndex(f=>ManualSlabSchedule.IsManual(f[1])&&ManualSlabSchedule.Read(f[1]).Mark==value.Mark);if(index<0)throw new Exception("Manual source was not found.");sourceFiles[index]=new[]{"Manual "+value.Mark+".xml",ManualSlabSchedule.Write(value)};schedules[value.Mark]=value;var oldDefaults=SlabEntryOptions.Defaults(previous);var defaults=SlabEntryOptions.Defaults(value);bool before=filling;filling=true;try{foreach(DataGridViewRow row in grid.Rows)if(!row.IsNewRow&&Cell(row,1)==value.Mark)for(int n=1;n<=4;n++)if(Cell(row,n+6)==oldDefaults[n])row.Cells[n+6].Value=defaults[n];}finally{filling=before;}UpdateLoadedDxf();Recalculate();}
 void ManageManualReinforcement(){Guard();grid.EndEdit();using(var form=new Form{Text="Manual slab reinforcement schedules",Width=1000,Height=680,MinimumSize=new Size(760,520),StartPosition=FormStartPosition.CenterParent}){var list=new ListView{Dock=DockStyle.Fill,View=View.Details,FullRowSelect=true,MultiSelect=false};list.Columns.Add("Slab mark",220);list.Columns.Add("Thickness mm",140);list.Columns.Add("Bar groups",140);list.Columns.Add("Takeoff rows using schedule",230);var details=new TextBox{Dock=DockStyle.Bottom,Height=240,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false};var tools=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,Padding=new Padding(12)};var edit=new Button{Text="Edit selected",AutoSize=true};var remove=new Button{Text="Delete selected",AutoSize=true};var close=new Button{Text="Close",AutoSize=true,DialogResult=DialogResult.Cancel};tools.Controls.AddRange(new Control[]{edit,remove,close});Action refresh=()=>{list.Items.Clear();foreach(var source in sourceFiles.Where(s=>ManualSlabSchedule.IsManual(s[1]))){var schedule=ManualSlabSchedule.Read(source[1]);int uses=grid.Rows.Cast<DataGridViewRow>().Count(r=>!r.IsNewRow&&Cell(r,1)==schedule.Mark);var item=new ListViewItem(new[]{schedule.Mark,schedule.Thickness.ToString(CultureInfo.InvariantCulture),schedule.Bars.Count(b=>b!=null).ToString(),uses.ToString()}){Tag=schedule.Mark};list.Items.Add(item);}details.Text=list.Items.Count==0?"No manual reinforcement schedules have been added.":"Select a schedule to see its reinforcement.";if(list.Items.Count>0)list.Items[0].Selected=true;};list.SelectedIndexChanged+=(s,e)=>{if(list.SelectedItems.Count==0)return;string mark=Convert.ToString(list.SelectedItems[0].Tag);SlabScheduleRow schedule;if(!schedules.TryGetValue(mark,out schedule))return;details.Text=mark+" — "+schedule.Thickness+" mm"+Environment.NewLine+string.Join(Environment.NewLine,Enumerable.Range(0,9).Select(n=>SlabScheduleReader.Columns[n]+": "+(schedule.Bars[n]==null?"—":schedule.Bars[n].Raw)));};edit.Click+=(s,e)=>{if(list.SelectedItems.Count==0)return;var schedule=schedules[Convert.ToString(list.SelectedItems[0].Tag)];using(var dialog=new ManualSlabScheduleForm(schedule,true))if(dialog.ShowDialog(form)==DialogResult.OK){ReplaceManualSchedule(dialog.Value);refresh();}};remove.Click+=(s,e)=>{if(list.SelectedItems.Count==0)return;string mark=Convert.ToString(list.SelectedItems[0].Tag);int uses=grid.Rows.Cast<DataGridViewRow>().Count(r=>!r.IsNewRow&&Cell(r,1)==mark);if(MessageBox.Show(form,"Delete manual schedule "+mark+" and its "+uses+" takeoff row(s)?\nSave the POW first if you need a backup.","Delete manual reinforcement",MessageBoxButtons.YesNo,MessageBoxIcon.Warning,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;int index=sourceFiles.FindIndex(f=>ManualSlabSchedule.IsManual(f[1])&&ManualSlabSchedule.Read(f[1]).Mark==mark);if(index>=0)RemoveSourceAt(index);refresh();};form.Controls.Add(list);form.Controls.Add(details);form.Controls.Add(tools);form.CancelButton=close;refresh();PowTheme.Apply(form);form.ShowDialog(this);}}
}
}
